// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public { log = new Log(); c = new C(address(log)); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log));
        uint256 amt = bound(uint256(amount), 1, 5 ether);
        uint256 depositAmt = amt + 2 ether; // > MinDeposit (1 ether)

        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        uint256 lenBefore = log.History();

        vm.prank(actor);
        c.CashOut(amt);

        // Rule: every successful CashOut adds exactly one History entry.
        assertTrue(log.History() == lenBefore + 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether + 1, 1000 ether);
        vm.deal(actor, amount + amount);

        vm.prank(actor);
        c.Deposit{value: amount}();

        vm.prank(actor);
        c.CashOut(amount);

        uint256 len = c.TransferLog().History(0).length == 0 ? 0 : 0;
        // read the last logged message via the public History getter by iterating from 0 upward
        uint256 i = 0;
        bool found = false;
        while (true) {
            try c.TransferLog().History(i) returns (C.LogMessage memory) {
                i++;
            } catch {
                found = true;
                break;
            }
        }
        require(found && i > 0, "history empty");

        C.LogMessage memory last;
        try c.TransferLog().History(i - 1) returns (C.LogMessage memory m) {
            last = m;
        } catch {
            last = m0();
        }

        assertTrue(
            last.Sender == actor && last.Val == amount && keccak256(bytes(last.Data)) == keccak256(bytes("CashOut")),
            "successful CashOut must be recorded as the latest log message"
        );
    }

    function m0() internal pure returns (C.LogMessage memory m) {
        return m;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(address actor, uint256 depositAmount, uint256 outAmount, uint256 warpTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        depositAmount = bound(depositAmount, c.MinDeposit() + 1, 1000 ether);
        outAmount = bound(outAmount, 1, depositAmount);
        warpTime = bound(warpTime, 1, 2 ** 60);

        vm.deal(actor, depositAmount + 1 ether);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Time passes between deposit and cash-out so the timestamps differ.
        vm.warp(warpTime);

        vm.prank(actor);
        c.CashOut(outAmount);

        uint256 last = log.History(log.History() - 1);
        (, , uint256 val, uint256 time) = log.History(last); // placeholder-free getter unpack
        assertTrue(time == block.timestamp && val == outAmount && keccak256(bytes("")) == keccak256(bytes("")) || (time == block.timestamp && val == outAmount));
    }
}
